
const DATA=PAIJIAN_CONTENT.base;
const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages=['基础入门','大阿卡纳','小阿卡纳','宫廷牌','单张与三张牌'];
let user='我的体验';try{user=localStorage.getItem('paijian-demo-identity')||user}catch{};let state,tab='home',session=null,filter='大阿卡纳',cardSearch='',selectedCard=null,aiReply='';
function restore(){try{state=JSON.parse(localStorage.getItem('paijian-demo:'+user)||'{}')}catch{state={}}state={done:{},attempts:[],ratings:{},favorites:[],daily:{},journal:[],journalDraft:null,spreads:[],spreadDraft:null,personalMeanings:{},noteDrafts:{},spreadDrafts:{},...state};state.noteDrafts=state.noteDrafts||{};state.spreadDrafts=state.spreadDrafts||{};if(state.journalDraft)state.noteDrafts[state.journalDraft.id]={type:'life',...state.journalDraft};if(state.spreadDraft)state.spreadDrafts[state.spreadDraft.id]=state.spreadDraft;$('#identity').innerHTML='<span class="avatar">'+E(user[0])+'</span>'+E(user)+' · 本地身份'}
function save(){try{localStorage.setItem('paijian-demo:'+user,JSON.stringify(state));return true}catch{toast('暂未保存成功，请检查浏览器存储');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2600)}
const CARD_IMAGES=PAIJIAN_CONTENT.cardImages;
function cardImage(name,extra=""){return CARD_IMAGES[name]?'<img class="real-card '+extra+'" src="'+CARD_IMAGES[name]+'" alt="'+E(name)+'牌面" loading="lazy">':""}
function lessonCard(l){return l.card_name||''}
function art(name='愚者',n='0'){return cardImage(name)||'<div class="card-art"><strong>'+E(name)+'</strong><small>学习卡</small></div>'}
function day(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function ref(k){return '<details><summary>来源与说明</summary><p>'+E(k?.summary||'当前为教学概括草稿，仍需逐牌核验。')+'</p><p>'+E(k?.cautions||'本页主题用于学习讨论，不保证现实结果。')+'</p>'+(k?'<a href="'+E(k.source_url)+'" target="_blank" rel="noopener">查看原文来源</a>':'')+'</details>'}
function nextLesson(){return [...DATA.lessons].sort((a,b)=>lessonOrder(a)-lessonOrder(b)).find(l=>l.ready&&l.path_role!=='场景选学'&&!state.done[l.id])||DATA.lessons.find(l=>l.ready)}
function mastered(){const first=new Map();state.attempts.forEach(a=>{if(!first.has(a.qid))first.set(a.qid,a)});return [...first.values()].filter(a=>a.correct&&!a.revealed).length}
function due(){const latest=new Map();state.attempts.forEach(a=>{if(!a.revealed)latest.set(a.qid,a)});return [...latest.values()].filter(a=>!a.correct).map(a=>a.qid)}
function navigate(t){if(journalFlush){if(!journalFlush())return;journalFlush=null}if(t==='cards'){t='home';discoverMode='cards'}tab=t;session=null;selectedCard=null;aiReply='';render();window.scrollTo(0,0)}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(session)return lessonView();if(selectedCard)return cardView();if(tab==='home')home();if(tab==='courses')courses();if(tab==='cards')cards();if(tab==='mine')mine();if(tab==='journal')journal()}
function cardOrder(c){const part=c.card_id.split('-')[1];return ({M:0,C:100,S:200,P:300,W:400}[part[0]]??500)+Number(part.slice(1))}
function lessonOrder(l){return l.order??9999}
let feedFilter='全部',discoverMode='cards',journalCardFilter='',journalDateFilter='';
const STARTER={
L00:{goal:'能分清“看见的画面”和“自己的理解”。',observe:['例如：人物站在悬崖边，是可以指出的画面；“他很冲动”是你对画面的解释。'],explain:['先说你看到什么，再说它让你想到什么。这样解读才有依据。','每次练习先确认问题：你在讨论现状、需要留意的事，还是行动建议？同一张牌在不同位置回答的问题不同。'],example:'想尝试新爱好时，先描述愚者的姿态，再讨论自己愿意尝试什么、需要准备什么。'},
L01:{goal:'能把探索的主题与需要留意的边界一起表达。',observe:['看人物的步伐、朝向、脚边的小狗，以及前方悬崖。'],explain:['开放和探索是一种理解；悬崖也提醒我们观察现实条件。','在行动建议中，可以理解为尝试一个小步骤，同时做好准备，不能直接理解成“不用考虑风险”。'],example:'想报名一门新课程，可以先体验一节，同时了解费用和时间要求。'},
L02:{goal:'能从画面找到“运用手边资源”的依据。',observe:['看桌上的四种工具，再看人物一手向上、一手向下的姿态。'],explain:['桌上的工具让我们想到已有的资源与能力；人物的姿态可用于讨论如何将想法落实。','作为行动建议，先盘点你已经有的条件，再做一个具体步骤；这不保证事情一定成功。'],example:'准备读书分享，先用已有书籍和笔记做一版提纲，再检查缺少什么。'},
L03:{goal:'能区分耐心观察与无期限等待。',observe:['看两根柱子、帷幕和人物手中的卷轴。'],explain:['这些线索可以帮助讨论尚未明说的信息、安静观察和内在感受。','倾听直觉，也要检查事实。不能用这张牌断定别人隐藏了秘密。'],example:'还不清楚一件事时，先收集信息、记录感受，再作判断。'},
L04:{goal:'能用具体行为解释滋养与成长。',observe:['看植物、麦田、座椅，以及人物周围的自然环境。'],explain:['丰富的自然画面可用于理解照顾、创造和成长所需的条件。','滋养不只是付出，也包括休息、照顾自己和保持合适的边界。'],example:'想让学习持续下去，可以安排舒适环境、固定时间和休息。'},
L05:{goal:'能区分建立规则与过度控制。',observe:['看石质王座、人物的端坐姿态与背景山地。'],explain:['稳定的形态可以用来讨论结构、责任和边界。','在行动建议中，可以制定计划和明确分工；这不等于必须控制所有细节。'],example:'小组活动开始前，先明确谁负责什么、何时完成，同时留出协商空间。'}
};
for(const l of DATA.lessons){const e=STARTER[l.id];if(e){l.learning_goals=[e.goal];l.observation=e.observe;l.explanation=e.explain;l.examples=[e.example]}}
for(const l of DATA.lessons)for(const q of l.questions){if(q.prompt.includes('圣杯一、宝剑一、星币一、权杖一都带有')){q.options.find(o=>o.id==='A').feedback='数字可以提供线索，但只看数字会忽略花色和画面的差异。';q.options.find(o=>o.id==='B').feedback='正确。相同数字可帮助比较，但还要结合各张牌的花色与画面。';q.options.find(o=>o.id==='C').feedback='说得太绝对。相同数字仍可提供比较线索，只是不能直接当作相同牌义。';q.answer_key.reason='数字“一”可提供开端的比较线索，但圣杯、宝剑、星币和权杖的花色与画面不同，不能用数字代替具体观察。'}}
const DEEPER={
L01:['为什么同时看人物与悬崖：迈步和轻装可支持探索的理解，悬崖则让我们检查边界。不能因为想表达“勇敢”，就省略边缘的线索。','对比例子：回答“我现在的状态”时，可讨论开放或准备不足；回答“建议”时，可讨论先试一个小步骤并核对条件。不是所有问题都需要同一种回答。'],
L02:['从工具到资源：桌上的物件提供“已有条件”的画面依据。解读时要问现实中对应什么，例如资料、技能、时间；如果没有对应信息，就先询问，不要自行编造。','避免误读：画面中的主动姿态不等于无所不能。行动建议要落到可执行步骤，例如先列提纲，再补资料；“一定成功”没有足够依据。'],
L03:['帷幕与卷轴可以启发对信息的讨论，但“没有看见”不能推出“别人一定隐瞒”。先说明这是可能的理解，再检查事实。','耐心观察不等于无限等待。可以设定一个信息收集期限，届时根据已知条件重新判断。'],
L04:['植物与麦田支持对成长条件的讨论。把“滋养”说具体：谁需要什么条件、你能提供什么、你自己需要什么。','不要把皇后的形象固定对应某种性别或身份，也不能仅凭此牌判断生育结果。学习重点是画面线索与问题的联系。'],
L05:['王座与端坐可支持稳定和规则的理解，但稳定不是僵硬。先问哪些约定帮助事情进行，再问哪些约定需要调整。','同样的结构主题：现状位可能讨论已有制度；建议位可能讨论设立边界。不要仅凭人物外观认定现实中的领导或父亲。']};
for(const l of DATA.lessons){if(DEEPER[l.id])l.explanation.push(...DEEPER[l.id])}
const spreadLesson=DATA.lessons.find(l=>l.id==='L14');spreadLesson.learning_goals=['能按问题、牌位、单牌依据和组合关系完成三张牌解读，再记录后续变化。'];spreadLesson.observation=['先读问题和范围，再看每张牌的画面；在纸上标出三个牌位，不先急着串成故事。'];spreadLesson.explanation=['第一步：明确问题。例如“本周准备读书分享，我需要留意什么？”比“我会成功吗？”更便于讨论行动。','第二步：抽牌前确定牌位。入门可用“现状、需要留意、行动建议”；不要看到牌之后临时改牌位来迎合解释。','第三步：分别写每张牌的一处画面依据，以及它如何回答所在位置。先单牌，再组合。','第四步：找关系。哪些牌谈相同主题？哪些牌形成张力？只连接已有线索，不添加没有证据的人物或事件。','第五步：落到一个可执行步骤，并注明哪里还不确定。过几天记录实际经历与新的理解，保留原来的判断。','正逆位：先确定练习规则再解读。初学者可以先只用正位；加入逆位后，也应写明采用的是受阻、过度还是内在化角度。'];spreadLesson.examples=['教学示范（并非实际抽牌）：现状是魔术师，可从桌上工具讨论已有资源；需要留意是女祭司，可讨论尚需了解的信息；行动建议是皇帝，可讨论安排分工与时间。组合理解：先盘点资源、补齐信息，再制定计划。','不充分的连接：“这三张牌说明分享一定成功。”它没有回答具体准备工作，也把主题转换成了结果保证。','记录示范：问题——本周如何准备分享；当时解释——先整理材料并确认听众需求；后续经历——听众更需要入门例子；新的理解——原先对“已有资源”的理解还应包括听众背景。'];
