function expressionGuide(){return '<details class="study-block"><summary>试着用自己的话表达</summary><p>我看见……（画面事实）</p><p>这让我想到……（可能理解）</p><p>在这个问题里，我可以……（有条件的行动）</p><p class="tip">可以口述或在心里回答。参考方法：先给出画面依据，再表达解释；不保证现实结果。</p></details>'}
const POSITION_DEMO=[{name:'现状',card:'魔术师',task:'现在有哪些资源与条件？',evidence:'桌上的工具',reading:'可以先盘点已有书籍、笔记和分享经验。'},{name:'需要留意',card:'女祭司',task:'还有哪些信息需要确认？',evidence:'帷幕和卷轴',reading:'确认听众背景与期待，不能据此断言有人隐瞒。'},{name:'行动建议',card:'皇帝',task:'下一步可以做什么？',evidence:'石质王座与端坐姿态',reading:'安排准备步骤与时间，同时允许调整。'}];
function spreadTeaching(){return '<section class="panel"><h2>三张牌 · 完整示范</h2><p>问题：本周准备读书分享，需要留意什么？</p><p class="tip">教学组合，并非实际抽牌。点击牌位查看推理。</p><div class="spread-layout">'+POSITION_DEMO.map((d,i)=>'<button class="secondary" data-demo-position="'+i+'">'+(i+1)+' · '+d.name+'</button>').join('')+'</div><div id="demo-position-detail">'+demoPosition(0)+'</div><h3>组合成一句话</h3><p>先盘点资源，确认信息，再安排准备步骤。</p><h3>反例与原因</h3><p>“分享一定成功”并未说明具体依据，把教学主题当成了结果保证。</p><h3>后续如何回看</h3><p>保留原解释，再记录听众实际需求、做过的调整和仍不确定的地方。</p></section>'}
function demoPosition(i){const d=POSITION_DEMO[i];return cardImage(d.card)+'<h3>'+d.name+'：'+d.task+'</h3><p>画面依据：'+d.evidence+'</p><p>示范解释：'+d.reading+'</p>'}
function bindSpreadTeaching(){document.querySelectorAll('[data-demo-position]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-demo-position]').forEach(x=>x.classList.toggle('selected',x===b));$('#demo-position-detail').innerHTML=demoPosition(Number(b.dataset.demoPosition))})}
function spreadLayout(labels,entries){return '<div class="spread-layout">'+labels.map((l,i)=>'<button class="secondary" data-position="'+i+'">'+(i+1)+' · '+E(l)+(entries[i]?.card?'<br>'+E(DATA.cards.find(c=>c.card_id===entries[i].card)?.name):'')+'</button>').join('')+'</div>'}

function personalSummary(id){const m=state.personalMeanings[id];return m?'<section class="panel"><h2>目前的个人总结</h2>'+[['summary','理解'],['support','支持经历'],['counterexample','反例'],['questions','疑问']].map(([k,label])=>'<h3>'+label+'</h3><p class="note-text">'+E(m[k]||'暂未填写')+'</p>').join('')+'<small>'+E(m.updated)+'</small></section>':''}
function editMeaning(c){const old=state.personalMeanings[c.card_id]||{};const fields=[['summary','目前的理解'],['support','支持这一理解的经历'],['counterexample','反例或不适用的情况'],['questions','仍有疑问']];$('#app').innerHTML='<div class="narrow journal-editor"><h1>'+E(c.name)+' · 我的牌意</h1><p class="tip">个人总结与资料解释分开，修改会保留历史版本。</p>'+fields.map(([k,label])=>'<label>'+label+'<textarea id="meaning-'+k+'">'+E(old[k]||'')+'</textarea></label>').join('')+'<button class="primary" id="meaning-save">保存总结</button><button class="link" id="meaning-back">返回个人牌页</button><details><summary>历史版本（'+(old.history||[]).length+'）</summary>'+(old.history||[]).map(h=>'<p class="note-text">'+E(h.updated)+'<br>'+E(h.summary)+'<br>'+E(h.counterexample)+'</p>').join('')+'</details></div>';$('#meaning-back').onclick=personalCards;$('#meaning-save').onclick=()=>{const values=Object.fromEntries(fields.map(([k])=>[k,$('#meaning-'+k).value]));if(!Object.values(values).some(v=>v.trim())){toast('至少写一点理解或疑问');return}state.personalMeanings[c.card_id]={...values,updated:new Date().toISOString(),history:old.updated?[...(old.history||[]),{summary:old.summary,support:old.support,counterexample:old.counterexample,questions:old.questions,updated:old.updated}]:[]};if(save()){toast('个人总结已保存');personalCards()}else if(old.updated)state.personalMeanings[c.card_id]=old;else delete state.personalMeanings[c.card_id]}}
function mine(){$('#app').innerHTML='<div class="eyebrow">MY LEARNING</div><h1>我的学习</h1><p class="muted">当前身份：'+E(user)+'。数据保存在此浏览器，不是云端账号。</p><div class="stats"><div class="stat"><b>'+Object.keys(state.done).length+'</b><span>已完成课程</span></div><div class="stat"><b>'+state.attempts.length+'</b><span>练习作答记录</span></div><div class="stat"><b>'+state.favorites.length+'</b><span>收藏卡牌</span></div></div><div class="grid"><section class="panel"><h2>最近学习</h2>'+Object.entries(state.done).map(([id,d])=>'<div class="path-item"><span class="circle">✓</span><div>'+E(DATA.lessons.find(x=>x.id===id)?.title||'旧版课程记录 '+id)+'<br><small class="muted">'+E(d)+' · '+E(state.ratings[id]||'未评价')+'</small></div></div>').join('')+(Object.keys(state.done).length?'':'<div class="empty">从第一节短课开始留下记录。</div>')+'</section><section class="panel"><h2>我的收藏</h2>'+state.favorites.map(id=>'<button class="option" data-card="'+id+'">'+E(DATA.cards.find(c=>c.card_id===id).name)+' →</button>').join('')+(state.favorites.length?'':'<p class="muted">在图鉴里收藏你想再看的牌。</p>')+'</section></div><section class="panel"><h2>个人牌页</h2><p class="tip">查看同一张牌的历次理解与生活记录。</p><button class="primary" id="personal-cards">我的牌笔记</button></section>';$('#app').innerHTML+='<section class="panel appearance-panel"><h2>外观</h2>'+appearanceChoices()+'<p class="theme-explanation">跟随手机系统，或选择适合当前阅读环境的模式。</p></section>';bindAppearanceChoices();bindCardButtons();$('#personal-cards').onclick=personalCards}

function bindStarts(){document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelectorAll('#app [data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab))}
function bindCardButtons(){document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{selectedCard=b.dataset.card;aiReply='';render();window.scrollTo(0,0)})}
$('#identity').onclick=()=>{$('#overlay').innerHTML='<div class="modal-wrap"><div class="modal"><h2>切换体验身份</h2><p class="muted">每个名字保存一份独立本地记录。此 Demo 不进行真实登录，也不会同步到朋友的设备。</p><input id="nickname" maxlength="24" placeholder="例如：我的体验、小林"><div class="row"><button class="secondary" id="cancel">取消</button><button class="primary" id="switch">进入体验</button></div></div></div>';$('#nickname').focus();$('#cancel').onclick=()=>$('#overlay').innerHTML='';$('#switch').onclick=()=>{const n=$('#nickname').value.trim();if(!n)return;user=n;try{localStorage.setItem('paijian-demo-identity',user)}catch{toast('身份仅在本次打开期间有效')}restore();$('#overlay').innerHTML='';navigate('home')}};

let appearanceMode=document.documentElement?.dataset?.themePreference||'system';
const appearanceMedia=typeof matchMedia==='function'?matchMedia('(prefers-color-scheme: dark)'):null;
function appearanceChoices(){return '<div class="theme-options" role="group" aria-label="外观模式">'+[['system','跟随系统'],['light','浅色'],['dark','夜间']].map(([k,label])=>'<button class="theme-choice" data-appearance="'+k+'" aria-pressed="'+(appearanceMode===k)+'">'+label+'</button>').join('')+'</div>'}
function applyAppearance(mode){if(!['system','light','dark'].includes(mode))mode='system';appearanceMode=mode;const dark=mode==='dark'||(mode==='system'&&!!appearanceMedia?.matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.themePreference=mode;const meta=document.getElementById('theme-color');if(meta)meta.content=dark?'#17131d':'#ffffff';try{localStorage.setItem('paijian-appearance',mode)}catch{}document.querySelectorAll('[data-appearance]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.appearance===mode)));const open=document.getElementById('appearance-open');if(open){open.textContent=dark?'☾':'☼';open.setAttribute('aria-label','外观设置，当前'+(dark?'夜间模式':'浅色模式'))}}
function bindAppearanceChoices(){document.querySelectorAll('[data-appearance]').forEach(b=>b.onclick=()=>applyAppearance(b.dataset.appearance))}
function openAppearance(){const previous=document.activeElement;$('#overlay').innerHTML='<div class="modal-wrap theme-sheet"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="appearance-title"><h2 id="appearance-title">外观</h2>'+appearanceChoices()+'<p class="theme-explanation">跟随手机系统，也可以单独选择浅色或夜间。牌面保留原色，方便观察细节。</p><button class="secondary" id="appearance-close">完成</button></section></div>';bindAppearanceChoices();const close=()=>{$('#overlay').innerHTML='';previous?.focus?.();document.removeEventListener?.('keydown',keys)};const keys=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const buttons=Array.from(document.querySelectorAll('#overlay button'));const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};$('#appearance-close').onclick=close;document.addEventListener?.('keydown',keys);document.querySelector('[data-appearance="'+appearanceMode+'"]')?.focus?.()}
if(appearanceMedia?.addEventListener)appearanceMedia.addEventListener('change',()=>{if(appearanceMode==='system')applyAppearance('system')});
$('#appearance-open').onclick=openAppearance;applyAppearance(appearanceMode);

document.querySelectorAll('nav [data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));restore();if(state.textbookContentRevision!=='2026-10-08'){delete state.resume;state.textbookContentRevision='2026-10-08';save()}render();
